class Solution:
    def minFlips(self, s: str) -> int:
        n = len(s)
        m = s.count('1')
        z = n - m
        ans = min(m, z)
        if m >= 1:
            ans = min(ans, m - 1)
        if n >= 2:
            mid_ones = m - (s[0] == '1') - (s[-1] == '1')
            d = (s[0] != '1') + (s[-1] != '1') + mid_ones
            ans = min(ans, d)
        return ans

