class Solution {
public:
    int minFlips(string s) {
        int n = s.size();
        long long m = count(s.begin(), s.end(), '1');
        long long z = n - m;
        long long ans = min(m, z);
        if (m >= 1) ans = min(ans, m - 1);
        if (n >= 2) {
            long long midOnes = m - (s[0] == '1') - (s[n - 1] == '1');
            long long d = (s[0] != '1') + (s[n - 1] != '1') + midOnes;
            ans = min(ans, d);
        }
        return (int)ans;
    }
};

