class Solution {
    public int minFlips(String s) {
        int n = s.length();
        long m = 0;
        for (char c : s.toCharArray()) if (c == '1') m++;
        long z = n - m;
        long ans = Math.min(m, z);
        if (m >= 1) ans = Math.min(ans, m - 1);
        if (n >= 2) {
            long midOnes = m - (s.charAt(0) == '1' ? 1 : 0) - (s.charAt(n - 1) == '1' ? 1 : 0);
            long d = (s.charAt(0) != '1' ? 1 : 0) + (s.charAt(n - 1) != '1' ? 1 : 0) + midOnes;
            ans = Math.min(ans, d);
        }
        return (int) ans;
    }
}

