class Solution {
    public int minFlips(String s) {
        int n = s.length(), m = 0;
        for (int i = 0; i < n; i++) if (s.charAt(i) == '1') m++;
        int z = n - m;
        int ans = Math.min(m, z);
        if (m >= 1) ans = Math.min(ans, m - 1);
        if (n >= 2) {
            int f = s.charAt(0) == '1' ? 1 : 0;
            int l = s.charAt(n - 1) == '1' ? 1 : 0;
            ans = Math.min(ans, (1 - f) + (1 - l) + (m - f - l));
        }
        return ans;
    }
}

